'use client';
import {useMemo,useState} from 'react';
type NumberField={label:string;value:number;set:(value:number)=>void};
export default function Orcamentos(){const [area,setArea]=useState(100);const [workers,setWorkers]=useState(2);const [hours,setHours]=useState(16);const [hourRate,setHourRate]=useState(18);const [materialCost,setMaterialCost]=useState(12);const [margin,setMargin]=useState(35);const costs=useMemo(()=>{const material=area*materialCost;const labour=workers*hours*hourRate;const cost=material+labour;const sale=margin<100?cost/(1-margin/100):0;return {material,labour,cost,sale,profit:sale-cost};},[area,workers,hours,hourRate,materialCost,margin]);const fields:NumberField[]=[{label:'Área (m²)',value:area,set:setArea},{label:'Trabalhadores',value:workers,set:setWorkers},{label:'Horas totais',value:hours,set:setHours},{label:'Valor/hora (€)',value:hourRate,set:setHourRate},{label:'Material €/m²',value:materialCost,set:setMaterialCost},{label:'Margem pretendida (%)',value:margin,set:setMargin}];return <main style={{padding:32,fontFamily:'Arial',maxWidth:900}}><h1>Novo orçamento</h1><p>Calculadora base: altera os valores e vê imediatamente o custo, preço e lucro estimado.</p><div style={{display:'grid',gap:12,maxWidth:500}}>{fields.map(f=><label key={f.label}>{f.label}<input type="number" value={f.value} onChange={e=>f.set(Number(e.target.value))} style={{display:'block',width:'100%',padding:9,marginTop:4}}/></label>)}</div><section style={{marginTop:25,padding:20,border:'1px solid #ddd',borderRadius:12}}><h2>Resumo</h2><p>Materiais: <strong>€{costs.material.toFixed(2)}</strong></p><p>Mão de obra: <strong>€{costs.labour.toFixed(2)}</strong></p><p>Custo total: <strong>€{costs.cost.toFixed(2)}</strong></p><p>Preço sugerido: <strong>€{costs.sale.toFixed(2)}</strong></p><p>Lucro estimado: <strong>€{costs.profit.toFixed(2)}</strong></p></section></main>}
